7: @MainActor private final class UsageModelLabel: NSTextView {
8:     let fullText: String
9:     init(_ text: String) {
10:         fullText=text
11:         let container=NSTextContainer(containerSize:NSSize(width:484,height:32))
12:         container.lineFragmentPadding=0;container.maximumNumberOfLines=2;container.lineBreakMode = .byTruncatingTail
13:         let manager=NSLayoutManager();manager.addTextContainer(container)
14:         let storage=NSTextStorage(string:text,attributes:[.font:NSFont.systemFont(ofSize:13),.foregroundColor:NSColor.white.withAlphaComponent(0.92)])
15:         storage.addLayoutManager(manager)
16:         super.init(frame:.zero,textContainer:container)
17:         isEditable=false;isSelectable=false;drawsBackground=false;textContainerInset = .zero
18:         toolTip=text;setAccessibilityLabel(text)
19:         manager.ensureLayout(for:container)
20:     }
21:     required init?(coder:NSCoder) {nil}
22:     override var intrinsicContentSize:NSSize {
23:         NSSize(width:484,height:ceil(layoutManager!.usedRect(for:textContainer!).height))
24:     }
25:     var truncated:Bool {
26:         let manager=layoutManager!;let range=manager.glyphRange(for:textContainer!)
27:         guard range.length>0 else {return false}
28:         return manager.truncatedGlyphRange(inLineFragmentForGlyphAt:NSMaxRange(range)-1).location != NSNotFound
29:     }
30: }
