33: @MainActor private final class UsageDetailDraftView: NSView, WS2LeaseContent {
34:     var onCancel: (() -> Void)?
35:     var inputIsCurrent: () -> Bool = { false }
36:     var interactionSize: NSSize { NSSize(width:520,height:ceil(body.fittingSize.height)+36) }
37:     private let body=NSStackView()
38:     private(set) var fields=[String:NSView]()
39:     private(set) var windows=[[String:Any]]()
40:     let modelName: String
41:     let shared: Bool
42:     init(reading: UsageReading?, contextUsed: Double?, model: String, shared: Bool, now: Double, calendar: Calendar) {
43:         self.modelName=model;self.shared=shared
44:         super.init(frame:NSRect(x:0,y:0,width:520,height:480))
45:         body.orientation = .vertical;body.alignment = .leading;body.spacing=12
46:         body.translatesAutoresizingMaskIntoConstraints=false;addSubview(body)
47:         NSLayoutConstraint.activate([body.leadingAnchor.constraint(equalTo:leadingAnchor,constant:18),body.topAnchor.constraint(equalTo:topAnchor,constant:18),body.widthAnchor.constraint(equalToConstant:484)])
48:         func field(_ key:String,_ text:String,_ size:CGFloat=13,_ weight:NSFont.Weight = .regular,_ secondary:Bool=false,_ wrap:Bool=false) -> NSTextField {
49:             let view=wrap ? NSTextField(wrappingLabelWithString:text) : NSTextField(labelWithString:text)
50:             view.font = .systemFont(ofSize:size,weight:weight)
51:             view.textColor = NSColor.white.withAlphaComponent(secondary ? 0.6 : 0.92)
52:             view.toolTip=text;view.identifier=NSUserInterfaceItemIdentifier(key)
53:             if wrap {view.maximumNumberOfLines=2;view.lineBreakMode = .byWordWrapping;view.preferredMaxLayoutWidth=484}
54:             else {view.lineBreakMode = .byTruncatingTail}
55:             view.setContentCompressionResistancePriority(.required,for:.vertical)
56:             fields[key]=view;return view
57:         }
58:         func add(_ view:NSView) {body.addArrangedSubview(view);view.widthAnchor.constraint(equalToConstant:484).isActive=true}
59:         add(field("title","用量",18,.semibold))
60:         add(field("source",shared ? "会话信息已隐藏" : "Codex · 演示账户",12,.regular,true))
61:         add(field("account-heading","账户额度",12,.semibold,true))
62:         let shown = shared ? [] : reading?.windows ?? []
63:         if shown.isEmpty {add(field("account-empty",shared ? "用量已隐藏" : "暂未读到用量",13,.regular,true))}
64:         for (index,window) in shown.enumerated() {
65:             guard let usage=UsageReading(windows:[window]).sessionUsage(now:now,calendar:calendar) else {continue}
66:             let name: String
67:             switch window.windowMinutes {
68:             case 300?: name="五小时额度"
69:             case 10080?: name="七天额度"
70:             case let minutes?: name="账户额度 · \(minutes) 分钟"
71:             case nil: name="账户额度"
72:             }
73:             let text=NSStackView();text.orientation = .vertical;text.alignment = .leading;text.spacing=3
74:             text.addArrangedSubview(field("window-\(index)-name",name,13,.medium))
75:             if let recovery=usage.recoveryDetail {text.addArrangedSubview(field("window-\(index)-recovery",recovery,12,.regular,true))}
76:             let amount=field("window-\(index)-amount","剩 \(usage.leftPercent)%",22,.semibold)
77:             amount.font = .monospacedDigitSystemFont(ofSize:22,weight:.semibold)
78:             if usage.isLow {amount.textColor = .systemOrange}
79:             amount.setContentCompressionResistancePriority(.required,for:.horizontal)
80:             amount.setContentHuggingPriority(.required,for:.horizontal)
81:             let spacer=NSView();spacer.setContentHuggingPriority(.init(1),for:.horizontal)
82:             let row=NSStackView(views:[text,spacer,amount]);row.orientation = .horizontal;row.alignment = .centerY;row.spacing=16
83:             add(row)
84:             windows.append(["name":name,"leftPercent":usage.leftPercent,"recovery":usage.recoveryDetail as Any? ?? NSNull(),"windowMinutes":window.windowMinutes as Any? ?? NSNull()])
85:         }
86:         let line=NSView();line.wantsLayer=true;line.layer?.backgroundColor=NSColor.white.withAlphaComponent(0.14).cgColor
87:         line.heightAnchor.constraint(equalToConstant:0.5).isActive=true;add(line)
88:         add(field("session-heading","当前会话",12,.semibold,true))
89:         add(field("project",shared ? "编程会话" : "设计工作间",15,.medium))
90:         if !shared {
91:             let label=UsageModelLabel(model);fields["model"]=label;add(label)
92:             add(field("effort","思考：深入",12,.regular,true))
93:             // This is a synthetic context value for the candidate, not a newly qualified wire channel.
94:             let snapshot=WS2SilentUsageSnapshot(selectedContext:contextUsed.map(WS2SilentUsageValue.provided) ?? .notProvided)
95:             let number=WS2SilentUsageRead.writtenNumber(snapshot.value(for:.selectedContext))
96:             let context=number.map {"上下文占用 \(Int($0))%"} ?? "暂未读到上下文"
97:             add(field("context",context,12,.regular,true))
98:         }
99:     }
100:     required init?(coder:NSCoder) {nil}
101:     func revoke() {inputIsCurrent={false};body.removeFromSuperview();fields.removeAll()}
102: }
