134:                     ownWindows.append(window);window.isReleasedWhenClosed=false;window.alphaValue=0
135:                     window.appearance=NSAppearance(named:parent);window.contentView=canvas
136:                     window.setFrame(NSRect(x:-8000,y:-8000,width:bounds.width,height:bounds.height),display:false)
