140:                     canvas.morph(to:bounds,style:.init(cornerRadius:24,allCorners:false,fill:.black,border:0.5),content:content,spring:nil){completions += 1}
141:                     canvas.placeAuthentication(in:NSRect(origin:.zero,size:size));canvas.layoutSubtreeIfNeeded()
142:                     try await Task.sleep(nanoseconds:150_000_000);canvas.layoutSubtreeIfNeeded()
143:                     var fields=[[String:Any]]()
144:                     for (key,label) in view.fields.sorted(by:{$0.key<$1.key}) {
145:                         var item:[String:Any]=["id":key,"tooltip":label.toolTip as Any? ?? NSNull(),"frame":box(label.convert(label.bounds,to:view)),"dark":label.effectiveAppearance.bestMatch(from:[.aqua,.darkAqua]) == .darkAqua]
146:                         if let text=label as? NSTextField {
147:                             item["text"]=text.stringValue;item["font"]=text.font?.pointSize ?? 0
148:                             item["maximumNumberOfLines"]=text.maximumNumberOfLines;item["wraps"]=(text.cell as? NSTextFieldCell)?.wraps ?? false
